import optax
from storage.praxis.synergy_model_ID897 import create_network as praxis_create_network

BASE_SEED = 7 # Changed for multi-seed replication
BATCH_SIZE = 64

def _define_hyperparameters():
    return {
        'd_model': 256,
        'kernel_size': 7,
        'dilations': [1, 2, 4, 8, 16],
        'motif_kernel_size': 5,
        'dropout_rate': 0.10,
        'reg_head_dropout': 0.05,
        'head_intermediate_dim': 128,
        'weight_decay': 0.012,
        'grad_clip': 1.0,
        'siamese_head_dense_dim': 64,
        'sgrna_len': 20,
    }

def create_network(hparams):
    return praxis_create_network(hparams)

def create_optimizer(learning_rate: float = 0.001):
    return optax.chain(
        optax.clip_by_global_norm(1.0),
        optax.adamw(learning_rate=learning_rate, weight_decay=0.012)
    )
